#[serde(tag = "_variant")]
pub enum FilesystemEntryNameAdmission {
    FilesystemEntryNameAdmitted(Rc<FilesystemEntryName>),
    FilesystemEntryNameRefused {
        name: String,
        cause: String,
    },
}
impl FilesystemEntryNameAdmission {
    pub fn name(&self) -> String {
        match self {
            FilesystemEntryNameAdmission::FilesystemEntryNameAdmitted(_) => panic!("no name on positional-payload variant"),
            FilesystemEntryNameAdmission::FilesystemEntryNameRefused { name: __val, .. } => __val.clone(),
        }
    }
    pub fn cause(&self) -> String {
        match self {
            FilesystemEntryNameAdmission::FilesystemEntryNameAdmitted(_) => panic!("no cause on positional-payload variant"),
            FilesystemEntryNameAdmission::FilesystemEntryNameRefused { cause: __val, .. } => __val.clone(),
        }
    }
}

pub fn filesystem_entry_name_text(component: Rc<FilesystemEntryName>) -> String {
    component.name()
}

pub fn admit_filesystem_entry_name(name: String) -> Rc<FilesystemEntryNameAdmission> {
    if (name.clone() == "".to_string()) {
        Rc::new(FilesystemEntryNameAdmission::FilesystemEntryNameRefused {
    name: name.clone(),
    cause: "an entry name is empty, so it names no child of any directory".to_string(),
})
    } else {
        if (name.clone() == ".".to_string()) {
            Rc::new(FilesystemEntryNameAdmission::FilesystemEntryNameRefused {
    name: name.clone(),
    cause: "`.` is the directory itself rather than an entry within it".to_string(),
})
        } else {
            if (name.clone() == "..".to_string()) {
                Rc::new(FilesystemEntryNameAdmission::FilesystemEntryNameRefused {
    name: name.clone(),
    cause: "`..` is the parent directory rather than an entry within it".to_string(),
})
            } else {
                if v1_rt::string_contains(&name, "/".to_string()) {
                    Rc::new(FilesystemEntryNameAdmission::FilesystemEntryNameRefused {
    name: name.clone(),
    cause: Rc::new(vec!["the entry name ".to_string(), name.clone(), " contains a path separator, so it is a PATH and not one direct ".to_string(), "child of the listed directory -- the listing would be asked about a different subject ".to_string(), "than the one the joined path names".to_string()]).join(&"".to_string()),
})
                } else {
                    if v1_rt::string_contains(&name, "\\".to_string()) {
                        Rc::new(FilesystemEntryNameAdmission::FilesystemEntryNameRefused {
    name: name.clone(),
    cause: Rc::new(vec!["the entry name ".to_string(), name.clone(), " contains a backslash, which is a path separator on some hosts ".to_string(), "this operation is implemented for -- so `..\\victim` is a parent traversal there while ".to_string(), "passing a check that rejects only `/`, which is the exact defect this carrier exists to ".to_string(), "make impossible. The grammar is the UNION over supported targets, not the one the author ".to_string(), "happens to be running on: a carrier that admits on Linux what it must refuse on Windows ".to_string(), "answers about a different subject depending on where it runs".to_string()]).join(&"".to_string()),
})
                    } else {
                        if v1_rt::string_contains(&name, "\x00".to_string()) {
                            Rc::new(FilesystemEntryNameAdmission::FilesystemEntryNameRefused {
    name: name.clone(),
    cause: Rc::new(vec!["the entry name ".to_string(), name.clone(), " contains a NUL, which terminates a C string -- so the name the ".to_string(), "host syscall sees is a PREFIX of the name the listing was asked about, and the two ".to_string(), "describe different subjects with no diagnostic between them".to_string()]).join(&"".to_string()),
})
                        } else {
                            if v1_rt::string_contains(&name, "\n".to_string()) {
                                Rc::new(FilesystemEntryNameAdmission::FilesystemEntryNameRefused {
    name: name.clone(),
    cause: Rc::new(vec!["the entry name ".to_string(), name.clone(), " contains a newline, which is the delimiter Filesystem.List uses ".to_string(), "between entries, so a membership test over the listing could answer yes for an entry that ".to_string(), "is not present".to_string()]).join(&"".to_string()),
})
                            } else {
                                if v1_rt::string_contains(&name, "\x0d".to_string()) {
                                    Rc::new(FilesystemEntryNameAdmission::FilesystemEntryNameRefused {
    name: name.clone(),
    cause: Rc::new(vec!["the entry name ".to_string(), name.clone(), " contains a carriage return, which can terminate a line in the ".to_string(), "listing wire format and make the membership test answer about a different spelling".to_string()]).join(&"".to_string()),
})
                                } else {
                                    Rc::new(FilesystemEntryNameAdmission::FilesystemEntryNameAdmitted(Rc::new(FilesystemEntryName {
    name: name.clone(),
})))
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

