#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum FilesystemFileObservation {
    FilesystemFileAbsent(Rc<FilesystemEstablishedAbsence>),
    FilesystemFileRead {
        path: String,
        content: String,
    },
    FilesystemFileIndeterminate {
        cause: String,
    },
    FilesystemFileObservationsDisagree {
        path: String,
        cause: String,
    },
    FilesystemFileSubjectRefused {
        directory: String,
        name: String,
        cause: String,
    },
}

pub fn filesystem_file_observation(listing: Rc<FilesystemListingObservation>, name: String, path: String, read: Rc<FilesystemReadOutcome>) -> Rc<FilesystemFileObservation> {
    match (*filesystem_entry_presence(listing, name)).clone() {
    FilesystemEntryPresence::FilesystemEntrySubjectRefused { directory: d, name: n, cause: c, .. } => Rc::new(FilesystemFileObservation::FilesystemFileSubjectRefused {
    directory: d.clone(),
    name: n.clone(),
    cause: c.clone(),
}),
    FilesystemEntryPresence::FilesystemEntryPresenceIndeterminate { cause: c, .. } => Rc::new(FilesystemFileObservation::FilesystemFileIndeterminate {
    cause: Rc::new(vec![c.clone(), " (at ".to_string(), path.clone(), ")".to_string()]).join(&"".to_string()),
}),
    FilesystemEntryPresence::FilesystemEntryAbsent(established) => match (*read.clone()).clone() {
    FilesystemReadOutcome::FilesystemReadRefused { error: _, .. } => Rc::new(FilesystemFileObservation::FilesystemFileAbsent(established.clone())),
    FilesystemReadOutcome::FilesystemReadSucceeded { content: _, .. } => Rc::new(FilesystemFileObservation::FilesystemFileObservationsDisagree {
    path: path.clone(),
    cause: Rc::new(vec![filesystem_established_absence_detail(established.clone()), ", and a read of ".to_string(), path.clone(), " then succeeded -- the two observations describe different instants and neither is".to_string(), " discarded, so the subject moved while it was being observed".to_string()]).join(&"".to_string()),
}),
},
    FilesystemEntryPresence::FilesystemEntryListed { .. } => match (*read.clone()).clone() {
    FilesystemReadOutcome::FilesystemReadRefused { error: e, .. } => Rc::new(FilesystemFileObservation::FilesystemFileIndeterminate {
    cause: Rc::new(vec![path.clone(), " is listed and could not be read, so it exists and its content is unavailable -- ".to_string(), e.clone()]).join(&"".to_string()),
}),
    FilesystemReadOutcome::FilesystemReadSucceeded { content: c, .. } => Rc::new(FilesystemFileObservation::FilesystemFileRead {
    path: path.clone(),
    content: c.clone(),
}),
},
}
}

pub fn filesystem_file_observation_below_ancestor(observation: Rc<FilesystemFileObservation>, ancestor: Rc<FilesystemEntryPresence>, path: String, read: Rc<FilesystemReadOutcome>) -> Rc<FilesystemFileObservation> {
    match (*observation.clone()).clone() {
    FilesystemFileObservation::FilesystemFileIndeterminate { cause: _, .. } => match (*ancestor.clone()).clone() {
    FilesystemEntryPresence::FilesystemEntryAbsent(established) => match (*read.clone()).clone() {
    FilesystemReadOutcome::FilesystemReadRefused { error: _, .. } => Rc::new(FilesystemFileObservation::FilesystemFileAbsent(established.clone())),
    FilesystemReadOutcome::FilesystemReadSucceeded { content: _, .. } => Rc::new(FilesystemFileObservation::FilesystemFileObservationsDisagree {
    path: path.clone(),
    cause: Rc::new(vec![filesystem_established_absence_detail(established.clone()), ", and a read of ".to_string(), path.clone(), " then succeeded -- the two observations describe different instants and neither is discarded".to_string()]).join(&"".to_string()),
}),
},
    FilesystemEntryPresence::FilesystemEntryListed { .. } => observation.clone(),
    FilesystemEntryPresence::FilesystemEntryPresenceIndeterminate { cause: _, .. } => observation.clone(),
    FilesystemEntryPresence::FilesystemEntrySubjectRefused { .. } => observation.clone(),
},
    FilesystemFileObservation::FilesystemFileAbsent(_) => observation.clone(),
    FilesystemFileObservation::FilesystemFileRead { .. } => observation.clone(),
    FilesystemFileObservation::FilesystemFileObservationsDisagree { .. } => observation.clone(),
    FilesystemFileObservation::FilesystemFileSubjectRefused { .. } => observation.clone(),
}
}

pub fn filesystem_established_absence_detail(absence: Rc<FilesystemEstablishedAbsence>) -> String {
    Rc::new(vec!["no ".to_string(), absence.name(), " is listed in ".to_string(), absence.directory()]).join(&"".to_string())
}

pub fn filesystem_established_absence_path(absence: Rc<FilesystemEstablishedAbsence>) -> String {
    {
        let directory = absence.directory();
if v1_rt::ends_with(directory.clone(), "/".to_string()) {
            Rc::new(vec![directory.clone(), absence.name()]).join(&"".to_string())
        } else {
            Rc::new(vec![directory.clone(), "/".to_string(), absence.name()]).join(&"".to_string())
        }
}
}

