pub async fn write(&self, path: String, content: String) -> std::result::Result<(bool, i64, String, String), std::boxed::Box<dyn std::error::Error>> {
        if self.dry_run.is_dry_run() {
            eprintln!("[dry-run] Write");
panic!("no mock data available for dry-run operation: Write")
} else {
            let file_path: String = format!("{}", path);
if file_path.is_empty() { return Err("file transport resolved to an empty path".into()); }
let file_io_error_kind = |host_err: &std::io::Error| -> String {
    match host_err.kind() {
        std::io::ErrorKind::NotFound => "not_found",
        std::io::ErrorKind::AlreadyExists => "already_exists",
        std::io::ErrorKind::PermissionDenied => "permission_denied",
        std::io::ErrorKind::NotADirectory => "not_a_directory",
        std::io::ErrorKind::CrossesDevices => "cross_device",
        _ => "other",
    }
    .to_string()
};
#[allow(unused_variables)]
let (file_success, file_content, file_error, file_byte_count, file_error_kind): (bool, String, String, i64, String) = {
    let payload_bytes = content.len() as i64;
    match std::fs::write(&file_path, content.as_bytes()) {
        Ok(()) => (true, String::new(), String::new(), payload_bytes, String::new()),
        Err(write_err) => (false, String::new(), format!("{}", write_err), 0i64, file_io_error_kind(&write_err)),
    }
};
Ok((file_success, file_byte_count, file_path.clone(), file_error.clone()))
}
}

